def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    import re as _re
    blob = json.dumps({"l": lessons, "q": questions}, ensure_ascii=False)
    if "ERPNext" in blob:
        problems.append(f"  {name}: ERPNext branding leakage")
    if _re.search(r"\b[Ll]aws?\b", blob):
        problems.append(f"  {name}: 'law' register leakage")
    for marker in ["certified professional", "the consultant", "consultants", "the academy",
                   "this academy", "engagement", "constitution", "costume", "scar tissue",
                   "witness", "testimony"]:
        if marker in blob.lower():
            problems.append(f"  {name}: banned marker '{marker}'")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.181.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.180.0"' not in init:
        sys.exit("ABORT: not at v3.180.0.")
    if "valuation" not in data:
        sys.exit("ABORT: valuation module not found in data file.")

    problems = _validate("INV5", LESSONS_I5, QUESTIONS_I5, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS_I5))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — INV5 spread failed: {dist}")
        sys.exit(1)
    total = sum(len(l["html"]) for l in LESSONS_I5)
    print(f"INV 5 v3: {len(LESSONS_I5)} chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS_I5):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["valuation"]["lessons"] = LESSONS_I5
    data["valuation"]["questions"] = bank
    data["valuation"]["desc"] = ("Valuation and the stock ledger in ZhiftERP: the Stock Ledger Entry column walk and the item-story read; Moving Average and FIFO with the container question worked under each; the four doors rates enter through — purchase receipts with the three-way match, the Landed Cost Voucher with its distribution bases, typed Stock Entry rates, and reconciliation rates — and the one door that does not exist; perpetual postings per document and the monthly stock-to-accounts tie-out at target zero; the repost machinery with its operating rules and the remediation-as-project discipline; and the five rate-error reads including the last-paid drift eye and the opening-rate sample.")

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.180.0"', '"3.181.0"'))
    print("  data: INVENTORY 5 lessons + bank REPLACED (style v3, strict manual register)")
    print("wrote __version__ -> 3.181.0")


if __name__ == "__main__":
    main()
